    public static int rptWord(emon.Port.Cells et, int a, int b, int c, int d, int e) {
        // Five code points appended to the text arena; answers where they start.
        int at = emon.Port.cellsLen(et);
        Evidence.etxAppendCp(et, a);
        Evidence.etxAppendCp(et, b);
        Evidence.etxAppendCp(et, c);
        Evidence.etxAppendCp(et, d);
        Evidence.etxAppendCp(et, e);
        return at;
    }
    public static int rptWitnessRow(emon.Port.Cells pl, int line, int font) {
        emon.Port.cellsPush(pl, 0);
        emon.Port.cellsPush(pl, line);
        emon.Port.cellsPush(pl, 100);
        emon.Port.cellsPush(pl, 100);
        emon.Port.cellsPush(pl, 1200);
        emon.Port.cellsPush(pl, 200);
        emon.Port.cellsPush(pl, font);
        emon.Port.cellsPush(pl, 0);
        return 0;
    }
    public static int rptReading(emon.Port.Cells oruns, emon.Port.Cells owords, int request, int t0, int t1) {
        // An OCR run of two five-letter words (their text at `t0`, `t1` in the text arena) answering `request`.
        int run = Evidence.orNew(oruns, 1, 0);
        int w0 = emon.Port.cellsLen(owords);
        Evidence.owNew(owords, 1, 100, 100, 600, 200, 100, 100, 600, 200, 0, 0, t0, 5, 0, 900, -1);
        Evidence.owNew(owords, 1, 700, 100, 1200, 200, 700, 100, 1200, 200, 0, 0, t1, 5, 0, 900, -1);
        Evidence.orSet(oruns, run, Evidence.orfRequest(), request);
        Evidence.orSet(oruns, run, Evidence.orfWfirst(), w0 / 28);
        Evidence.orSet(oruns, run, Evidence.orfWcount(), 2);
        return run;
    }
    public static void testWitnessesThatDisagreeWithTheTextEscalateThePage() {
        emon.Port.Cells pl = emon.Port.newCells();
        emon.Port.Cells fw = emon.Port.newCells();
        emon.Port.Cells fl = emon.Port.newCells();
        emon.Port.Cells et = emon.Port.newCells();
        emon.Port.Cells oruns = emon.Port.newCells();
        emon.Port.Cells owords = emon.Port.newCells();
        emon.Port.Cells scr = emon.Port.newCells();
        emon.Port.Cells ta = emon.Port.newCells();
        emon.Port.Cells tb = emon.Port.newCells();
        emon.Port.Cells tt = emon.Port.newCells();
        int tw0 = rptWord(et, 104, 101, 108, 108, 111);
        int tw1 = rptWord(et, 119, 111, 114, 108, 100);
        int rw0 = rptWord(et, 104, 101, 108, 108, 111);
        int rw1 = rptWord(et, 119, 111, 114, 108, 100);
        int bw0 = rptWord(et, 120, 121, 122, 122, 121);
        int bw1 = rptWord(et, 113, 119, 101, 114, 116);
        // the text layer: one line of two words, "hello world", font 7; two witness rows read that same line
        Evidence.wdNew(fw, 1, 100, 100, 600, 200, 100, 100, 600, 200, 0, 0, tw0, 5, 0, 900, -1);
        Evidence.wdNew(fw, 1, 700, 100, 1200, 200, 700, 100, 1200, 200, 0, 0, tw1, 5, 0, 900, -1);
        Evidence.wdSet(fw, 0, Evidence.wfFont(), 7);
        Evidence.wdSet(fw, 1, Evidence.wfFont(), 7);
        Evidence.lnNew(fl, 1, 100, 100, 1200, 200, 100, 100, 1200, 200, 0, 0, 0, 2);
        rptWitnessRow(pl, 0, 7);
        rptWitnessRow(pl, 0, 7);
        // two readings that say "hello world": the font's witnesses agree
        rptReading(oruns, owords, Rasterplan.riWitness() + 0, rw0, rw1);
        rptReading(oruns, owords, Rasterplan.riWitness() + 1, rw0, rw1);
        emon.Testport.assertEq(Rasterplan.rpWeak(2, 0, pl, fw, fl, et, Rasterplan.riWitness(), 0, 2, owords, oruns, scr, ta, tb, tt), 0, "agreeing witnesses: not weak");
        // two readings that do not: weak
        emon.Port.cellsDrop(oruns, 0);
        emon.Port.cellsDrop(owords, 0);
        rptReading(oruns, owords, Rasterplan.riWitness() + 0, bw0, bw1);
        rptReading(oruns, owords, Rasterplan.riWitness() + 1, bw0, bw1);
        emon.Testport.assertEq(Rasterplan.rpWeak(2, 0, pl, fw, fl, et, Rasterplan.riWitness(), 0, 2, owords, oruns, scr, ta, tb, tt), 1, "disagreeing witnesses: weak");
        // one disagreeing line alone is too little to say
        emon.Port.cellsDrop(oruns, 0);
        emon.Port.cellsDrop(owords, 0);
        rptReading(oruns, owords, Rasterplan.riWitness() + 0, bw0, bw1);
        emon.Testport.assertEq(Rasterplan.rpWeak(2, 0, pl, fw, fl, et, Rasterplan.riWitness(), 0, 1, owords, oruns, scr, ta, tb, tt), 0, "one compared line: not enough");
    }
